import { Component } from 'react'
import PropTypes from 'prop-types'
import ReactDOM from 'react-dom'
import { ToolTipStyle, ToolTipDataView } from './index.style'

class ToolTip extends Component {
  static propTypes = {
    dataView: PropTypes.element
  }

  state = {
    showTip: false
  }

  componentDidMount () {
    document.addEventListener('click', this.handleClickOutside, true)
  }

  componentWillUnmount () {
    document.removeEventListener('click', this.handleClickOutside, true)
  }

  handleClickOutside = event => {
    const domNode = ReactDOM.findDOMNode(this)
    if (!domNode || !domNode.contains(event.target)) {
      this.setState({
        showTip: false
      })
    }
  }

  checkSafeAreaForToolTip = () => {
    // here we are calculating the safe area for the tooltip
    const element = document.getElementById('tooltip')
    if (element) {
      const clientRect = element.getClientRects()[0]
      // 30px is the padding of parent element from the left side
      // so place the check for -25
      if (clientRect.left < -25) {
        element.classList.add('tool-tip-pos-from-left')
      }
    }
  }

  handleShowToolTip = (e) => {
    e.stopPropagation()
    this.setState({
      showTip: true
    }, () => {
      this.checkSafeAreaForToolTip()
    })
  }

  handleCloseTip = (e) => {
    e.stopPropagation()
    this.setState({
      showTip: false
    })
  }

  render () {
    const { children, dataView, className, wrapperClassName, hideTip, hideCloseBtn } = this.props
    return (
      <ToolTipStyle className={wrapperClassName}>
        {
          this.state.showTip && dataView && (
            <ToolTipDataView id='tooltip' className={className}>
              <div className={`${!hideTip ? 'tip-body' : ''}`}>
                {
                  dataView
                }
              </div>
              {!hideCloseBtn && (
                <div className='tip-close' onClick={this.handleCloseTip}>
                  <i className='fas fa-times' />
                </div>
              )}
              {!hideTip && (
                <div className='tip' />
              )}
            </ToolTipDataView>
          )
        }
        <div onClick={this.handleShowToolTip}>
          {children}
        </div>
      </ToolTipStyle>
    )
  }
}

export default ToolTip
