import { createRef, Component } from 'react'
import PropTypes from 'prop-types'
import { PolicyAmountStyle } from './index.style'
import AmountDistribution from '../../containers/Private/Application/components/AmountDistribution'
import { Button } from '..'
import { LANG_STRINGS } from '../../lang'
import { MANUAL_ORDER } from '../../constants/pkgCode'
import { Row } from '../../commonStyle/index.style'
import { AgentColorPallette } from '../../configs/colorPallete'
import CustomText from '../CustomText/index'

class PolicyAmountDistribution extends Component {
  static propTypes = {
    id: PropTypes.string,
    position: PropTypes.string,
    pkgDetail: PropTypes.object,
    subTitle: PropTypes.string,
    btnText: PropTypes.string,
    discount: PropTypes.number,
    hideDiscount: PropTypes.bool,
    useInstalment: PropTypes.bool,
    instalmentDetails: PropTypes.object,
    onChoosePayment: PropTypes.func,
    showAgentCommission: PropTypes.bool,
    isShowTermsNConditions: PropTypes.bool,
    tncChecked: PropTypes.bool,
    onTnCClick: PropTypes.func,
    isShowConvertToPaylater: PropTypes.bool,
    isConvertToPaylaterChecked: PropTypes.bool,
    onConvertToPaylaterClick: PropTypes.func,
  }

  constructor(props) {
    super(props)
    this.state = {
      position: '',
    }
    this.payRef = createRef()
  }

  componentDidUpdate(prevProps) {
    if (
      JSON.stringify(prevProps.pkgDetail) !==
      JSON.stringify(this.props.pkgDetail)
    ) {
      const element = this.payRef.current
      const elemetHeight = element.offsetHeight
      const viewportHeight = Math.max(
        document.documentElement.clientHeight || 0,
        window.innerHeight || 0
      )
      if (elemetHeight * 2 > viewportHeight) {
        this.setState({
          position: 'relative',
        })
      }
    }
  }

  render() {
    const {
      id,
      className,
      position,
      pkgDetail,
      subTitle,
      btnText,
      onChoosePayment,
      discount,
      hideDiscount,
      showAgentCommission,
      isShowTermsNConditions,
      onTnCClick,
      tncChecked,
      hidePaymentBtn = false,
      isShowConvertToPaylater,
      isConvertToPaylaterChecked,
      onConvertToPaylaterClick,
      useInstalment,
      instalmentDetails,
    } = this.props
    const isManualOrder = pkgDetail.protection_case === MANUAL_ORDER

    return (
      <PolicyAmountStyle
        ref={this.payRef}
        position={position}
        className={className}
        style={{ position: this.state.position }}
      >
        <AmountDistribution
          id={id}
          isManualOrder={isManualOrder}
          pkgDetail={pkgDetail}
          discount={discount}
          isHideDiscountIcon
          hideNull={hideDiscount}
          useInstalment={useInstalment}
          instalmentDetails={instalmentDetails}
          showAgentCommission={showAgentCommission}
          subTitle={subTitle}
        />
        {isShowConvertToPaylater && (
          <div
            className="convert-to-paylater"
            onClick={onConvertToPaylaterClick}
          >
            <input type="checkbox" checked={isConvertToPaylaterChecked} />
            <CustomText
              size="14px"
              weight="600"
              color={AgentColorPallette.black}
              bottom="0"
            >
              {LANG_STRINGS.changeTransactionToPayLater}
            </CustomText>
          </div>
        )}
        {isShowTermsNConditions && !hidePaymentBtn && (
          <Row justify="center" onClick={onTnCClick}>
            <input type="checkbox" checked={tncChecked} />
            <CustomText
              color={AgentColorPallette.black}
              textAlign="center"
              bottom="16px"
            >
              &nbsp;{LANG_STRINGS.iAgreeWith}&nbsp;
            </CustomText>
            <CustomText
              color={AgentColorPallette.darkGold}
              textAlign="center"
              bottom="16px"
            >
              {LANG_STRINGS.termsConditions}
            </CustomText>
          </Row>
        )}
        {!hidePaymentBtn && (
          <Button
            onClick={onChoosePayment}
            className="choose-payment-btn"
            id={`${id}-Submit`}
          >
            {btnText || LANG_STRINGS.choosePayment}
          </Button>
        )}
      </PolicyAmountStyle>
    )
  }
}

export default PolicyAmountDistribution
